<?php
declare(strict_types=1);
namespace App\Interface\Http\Assistant\Controller;
use App\Application\Assistant\DTO\Request\CreateAssistantConversationRequestDto;use App\Application\Assistant\DTO\Request\CreateAssistantMessageRequestDto;use App\Application\Assistant\Service\CreateAssistantConversationService;use App\Application\Assistant\Service\ListAssistantConversationsService;use App\Application\Assistant\Service\ListAssistantMessagesService;use App\Application\Assistant\Service\ListAvailableAssistantSyllabiService;use App\Application\Assistant\Service\SendAssistantMessageService;use App\Application\Identity\DTO\Request\AccessTokenRequestDto;use App\Application\Identity\Service\AuthService;use App\Domain\Identity\Exception\UnavailableUserException;use App\Infrastructure\Http\ApiResponseFactory;use DomainException;use Psr\Http\Message\ResponseInterface;use Psr\Http\Message\ServerRequestInterface;
final class AssistantController { public function __construct(private readonly AuthService $auth,private readonly CreateAssistantConversationService $create,private readonly ListAssistantConversationsService $list,private readonly ListAssistantMessagesService $messages,private readonly SendAssistantMessageService $send,private readonly ListAvailableAssistantSyllabiService $syllabi,private readonly ApiResponseFactory $responses){} public function list(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a):ResponseInterface{return $this->respond($r,$s,$a,fn($u)=>$this->list->listForUser($u->id));} public function availableSyllabi(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a):ResponseInterface{return $this->respond($r,$s,$a,fn()=> $this->syllabi->list());} public function create(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,CreateAssistantConversationRequestDto $i):ResponseInterface{return $this->respond($r,$s,$a,fn($u)=>$this->create->createForUser($u->id,$i));} public function messages(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,string $id):ResponseInterface{return $this->respond($r,$s,$a,fn($u)=>$this->messages->listForUser($u->id,$id));} public function send(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,CreateAssistantMessageRequestDto $i):ResponseInterface{return $this->respond($r,$s,$a,fn($u)=>$this->send->sendForUser($u->id,$i));} private function respond(ServerRequestInterface $r,ResponseInterface $s,AccessTokenRequestDto $a,callable $action):ResponseInterface{try{$user=$this->auth->currentUser($a);return $this->responses->success($s,$action($user),(string)$r->getAttribute('request_id'));}catch(UnavailableUserException){return $this->responses->problem($s,'UNAUTHENTICATED','Credenciais invalidas ou expiradas.',401,(string)$r->getAttribute('request_id'));}catch(DomainException $e){return $this->responses->problem($s,'VALIDATION_FAILED',$e->getMessage(),422,(string)$r->getAttribute('request_id'));}} }
